cd /workspace/runtime/local/workspace/run-ceobench; cat > ent_stats.py <<'EOF'
import novamind_api as nm, json, os
from collections import defaultdict, Counter
since = int(os.environ.get('SINCE', 0))
rows = nm.query(f"""SELECT t.thread_id, c.group_id, t.turn_number, t.sender, t.day, t.seat_count, t.closed, t.close_reason, t.offer_json, t.message_text, t.thread_type
 FROM enterprise_turns t JOIN customers c ON c.customer_id=t.customer_id WHERE t.thread_id IN (SELECT thread_id FROM enterprise_turns WHERE day>{since} AND sender='customer') ORDER BY t.thread_id, t.turn_number""")['rows']
th = defaultdict(list)
for r in rows: th[r['thread_id']].append(r)
res = Counter(); acc_prices = defaultdict(list); counters = defaultdict(list)
for tid, msgs in th.items():
    g = msgs[0]['group_id']; last_offer = None
    for m in msgs:
        if m['sender'] == 'agent':
            o = json.loads(m['offer_json']); last_offer = o[0]['price_per_seat'] if o else None
        elif m['sender'] == 'customer' and m['day'] > since:
            o = json.loads(m['offer_json'] or '{}')
            kind = 'accept' if m['close_reason'] == 'accepted' else 'counter'
            res[(g, m['thread_type'], m['turn_number'], kind)] += 1
            if kind == 'accept': acc_prices[g].append((last_offer, msgs[0]['seat_count']))
            else: counters[(g, m['turn_number'])].append((last_offer, o.get('price')))
for k in sorted(res): print(k, res[k])
for g, v in acc_prices.items():
    seats = sum(s for _, s in v); rev = sum(p*s for p, s in v)
    print('ACCEPTED', g, len(v), 'seats', seats, 'avg $/seat', round(rev/seats, 2) if seats else None, Counter(p for p, _ in v))
for k, v in sorted(counters.items()):
    ps = sorted(c for _, c in v if c is not None)
    print('COUNTERS', k, len(v), 'median', ps[len(ps)//2] if ps else None, 'p25', ps[len(ps)//4] if ps else None, 'p75', ps[3*len(ps)//4] if ps else None)
n = nm.query(f"SELECT message, COUNT(*) n FROM notifications WHERE day>{since} AND type IN ('lead_lost','deal_won','customer_churned','churn') GROUP BY message ORDER BY n DESC LIMIT 15")['rows']
for r in n: print(r)
t = nm.query(f"SELECT type, COUNT(*) n FROM notifications WHERE day>{since} GROUP BY type")['rows']; print(t)
EOF
SINCE=70 ./novamind-operation python ent_stats.py

